62: static void UpdateLockCountLockable( LockMap& lockmap, size_t pos )
63: {
64:     auto& timeline = lockmap.timeline;
65:     bool isContended = lockmap.isContended;
66:     uint8_t lockingThread;
67:     uint8_t lockCount;
68:     uint64_t waitList;
69: 
70:     if( pos == 0 )
71:     {
72:         lockingThread = 0;
73:         lockCount = 0;
74:         waitList = 0;
75:     }
76:     else
77:     {
78:         const auto& tl = timeline[pos-1];
79:         lockingThread = tl.lockingThread;
80:         lockCount = tl.lockCount;
81:         waitList = tl.waitList;
82:     }
83:     const auto end = timeline.size();
84: 
85:     while( pos != end )
86:     {
87:         auto& tl = timeline[pos];
88:         const auto tbit = uint64_t( 1 ) << tl.ptr->thread;
89:         switch( (LockEvent::Type)tl.ptr->type )
90:         {
91:         case LockEvent::Type::Wait:
92:             waitList |= tbit;
93:             break;
94:         case LockEvent::Type::Obtain:
95:             assert( lockCount < std::numeric_limits<uint8_t>::max() );
96:             assert( ( waitList & tbit ) != 0 );
97:             waitList &= ~tbit;
98:             lockingThread = tl.ptr->thread;
99:             lockCount++;
100:             break;
101:         case LockEvent::Type::Release:
102:             assert( lockCount > 0 );
103:             lockCount--;
104:             break;
105:         default:
106:             break;
107:         }
108:         tl.lockingThread = lockingThread;
109:         tl.waitList = waitList;
110:         tl.lockCount = lockCount;
111:         if( !isContended ) isContended = lockCount != 0 && waitList != 0;
112:         pos++;
113:     }
114: 
115:     lockmap.isContended = isContended;
116: }
