118: static void UpdateLockCountSharedLockable( LockMap& lockmap, size_t pos )
119: {
120:     auto& timeline = lockmap.timeline;
121:     bool isContended = lockmap.isContended;
122:     uint8_t lockingThread;
123:     uint8_t lockCount;
124:     uint64_t waitShared;
125:     uint64_t waitList;
126:     uint64_t sharedList;
127: 
128:     if( pos == 0 )
129:     {
130:         lockingThread = 0;
131:         lockCount = 0;
132:         waitShared = 0;
133:         waitList = 0;
134:         sharedList = 0;
135:     }
136:     else
137:     {
138:         const auto& tl = timeline[pos-1];
139:         const auto tlp = (const LockEventShared*)(const LockEvent*)tl.ptr;
140:         lockingThread = tl.lockingThread;
141:         lockCount = tl.lockCount;
142:         waitShared = tlp->waitShared;
143:         waitList = tl.waitList;
144:         sharedList = tlp->sharedList;
145:     }
146:     const auto end = timeline.size();
147: 
148:     // ObtainShared and ReleaseShared should assert on lockCount == 0, but
149:     // due to the async retrieval of data from threads that's not possible.
150:     while( pos != end )
151:     {
152:         auto& tl = timeline[pos];
153:         const auto tlp = (LockEventShared*)(LockEvent*)tl.ptr;
154:         const auto tbit = uint64_t( 1 ) << tlp->thread;
155:         switch( (LockEvent::Type)tlp->type )
156:         {
157:         case LockEvent::Type::Wait:
158:             waitList |= tbit;
159:             break;
160:         case LockEvent::Type::WaitShared:
161:             waitShared |= tbit;
162:             break;
163:         case LockEvent::Type::Obtain:
164:             assert( lockCount < std::numeric_limits<uint8_t>::max() );
165:             assert( ( waitList & tbit ) != 0 );
166:             waitList &= ~tbit;
167:             lockingThread = tlp->thread;
168:             lockCount++;
169:             break;
170:         case LockEvent::Type::Release:
171:             assert( lockCount > 0 );
172:             lockCount--;
173:             break;
174:         case LockEvent::Type::ObtainShared:
175:             assert( ( waitShared & tbit ) != 0 );
176:             assert( ( sharedList & tbit ) == 0 );
177:             waitShared &= ~tbit;
178:             sharedList |= tbit;
179:             break;
180:         case LockEvent::Type::ReleaseShared:
181:             assert( ( sharedList & tbit ) != 0 );
182:             sharedList &= ~tbit;
183:             break;
184:         default:
185:             break;
186:         }
187:         tl.lockingThread = lockingThread;
188:         tlp->waitShared = waitShared;
189:         tl.waitList = waitList;
190:         tlp->sharedList = sharedList;
191:         tl.lockCount = lockCount;
192:         if( !isContended ) isContended = ( lockCount != 0 && ( waitList != 0 || waitShared != 0 ) ) || ( sharedList != 0 && waitList != 0 );
193:         pos++;
194:     }
195: 
196:     lockmap.isContended = isContended;
197: }
